const claim = $('展开任务').item.json;
const raw = $json;
const {snapshot:previousSnapshot,...task}=claim;
if (!Array.isArray(raw.messages)) throw new Error('Gmail did not return thread messages');
const aliases = new Set([claim.mailbox,...(claim.config.aliases||[])].map(x=>x.toLowerCase()));
function header(m,name){return (m.payload?.headers||[]).find(h=>h.name.toLowerCase()===name.toLowerCase())?.value||'';}
function address(s){const a=s.match(/<([^<>]+)>/);const v=(a?a[1]:s).trim().toLowerCase();return /^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$/.test(v)?v:'';}
function decode(s){return s?Buffer.from(s,'base64url').toString('utf8'):'';}
function parts(p,m,out){if(!p)return;
 if(p.filename||p.body?.attachmentId)out.attachments.push({message_id:m.id,attachment_id:p.body?.attachmentId||null,filename:p.filename||'',mime_type:p.mimeType,size:p.body?.size||0});
 if(!p.filename&&p.mimeType==='text/plain'&&p.body?.data)out.text.push(decode(p.body.data));
 if(!p.filename&&p.mimeType==='text/html'&&p.body?.data)out.html.push(decode(p.body.data));
 for(const a of p.parts||[])parts(a,m,out);
}
const messages=[...raw.messages].filter(m=>!(m.labelIds||[]).includes('DRAFT')).sort((a,b)=>Number(a.internalDate)-Number(b.internalDate)||a.id.localeCompare(b.id));
const history=messages.map(m=>{const o={text:[],html:[],attachments:[]};parts(m.payload,m,o);const text=o.text.join('\n')||o.html.join('\n').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>');const from=header(m,'From');return {id:m.id,at:Number(m.internalDate),from,to:header(m,'To'),cc:header(m,'Cc'),subject:header(m,'Subject'),message_id:header(m,'Message-ID'),reply_to:header(m,'Reply-To'),body:text,body_complete:!!text.trim(),staff:(m.labelIds||[]).includes('SENT')||aliases.has(address(from)),attachments:o.attachments};});
const target=[...history].reverse().find(m=>!m.staff);
const latest=history[history.length-1];
const fingerprint=messages.map(m=>m.id).sort().join(',');
const bodyChars=history.reduce((n,m)=>n+m.body.length,0);
const reasons=[];
if(!target)reasons.push('no_customer_message');
if(target&&!target.body_complete&&!target.attachments.length)reasons.push('empty_customer_message');
if(history.some(m=>!m.body_complete&&!m.attachments.length))reasons.push('some_message_body_unavailable');
if(bodyChars>(claim.config.max_context_chars||80000))reasons.push('thread_exceeds_context_limit');
const addr=target?address(target.reply_to||target.from):'';
if(target&&!addr)reasons.push('ambiguous_reply_address');
// Full content stays in raw_thread in PostgreSQL. Long threads are routed to human, never silently truncated for a model.
return {json:{...task,raw_thread:raw,thread_id:raw.id,fingerprint,history,subject:target?.subject||'',current_message:target||null,reply_target:{address:addr,message_id:target?.message_id||'',gmail_id:target?.id||''},context_errors:reasons,already_answered:!!latest?.staff,review_feedback:claim.snapshot?.review_feedback||''}};

