const ctx=$('读取数据库上下文').item.json.context;
const triage=$('解析邮件分类').item.json.triage;
let d=$json.output;let parseError=false;
try{if(typeof d==='string')d=JSON.parse(d.replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,''));}catch(e){parseError=true;d={};}
d=d||{};
const steps=Array.isArray($json.intermediateSteps)?$json.intermediateSteps:[];
const evidence=steps.map(s=>({tool:s.action?.tool||s.tool||'',input:s.action?.toolInput||{},result:s.observation??s.output??null}));
const errors=[];
if(evidence.some(e=>/"isError"\s*:\s*true|"error"\s*:/i.test(JSON.stringify(e.result))))errors.push('tool_error_requires_review');
if(parseError)errors.push('draft_json_invalid');
if(typeof d.draft_body!=='string'||!d.draft_body.trim())errors.push('draft_empty');
if(!['answer','clarification','human'].includes(d.kind))errors.push('draft_kind_invalid');
if(d.needs_human!==false)errors.push(d.human_reason||'agent_requests_human');
if(d.kind==='answer'&&!evidence.some(e=>e.result!==null&&!/"isError"\s*:\s*true|"error"\s*:/i.test(JSON.stringify(e.result))))errors.push('no_recorded_tool_evidence');
const attachments=ctx.current_message?.attachments||[];
// Inspecting evidence requires a real configured tool; conservatively retain human review for attachments.
if(attachments.length)errors.push('customer_attachments_require_human_verification');
if((ctx.context_errors||[]).length)errors.push(...ctx.context_errors);
return {json:{mailbox:ctx.mailbox,thread_id:ctx.thread_id,version:ctx.version,lease_token:ctx.lease_token,fingerprint:ctx.fingerprint,
status:errors.length?'needs_human':'pending_review',draft_body:typeof d.draft_body==='string'?d.draft_body:'',triage,draft:d,tool_evidence:evidence,review_reasons:errors}};

const p=$json,c=$('读取数据库上下文').item.json.context;
const t=p.triage||{},d=p.draft||{},allowed={order_number:'Your order number',product_model:'The product model',issue_description:'A brief description of the issue'};
const missing=Array.isArray(d.missing_info)?[...new Set(d.missing_info)]:[];
const required=Array.isArray(t.missing_info)?t.missing_info:[],provided=Array.isArray(t.provided_info)?t.provided_info:[];
const history=c.history||[],text=history.map(m=>m.body||'').join('\n');
let ok=c.config.auto_clarification===true&&p.status==='pending_review'&&d.kind==='clarification'&&missing.length>0&&missing.every(k=>allowed[k]&&required.includes(k)&&!provided.includes(k));
if(history.some(m=>(m.attachments||[]).length))ok=false;
if(missing.includes('order_number')&&/(?:\b\d{5,}\b|\b\d{3}-\d{7}-\d{7}\b|order\s*(?:number|#|no\.?|id)\s*[:#]?\s*[A-Z0-9-]{3,})/i.test(text))ok=false;
if(missing.includes('product_model')&&/loona|clicbot|deskmate|petbot/i.test(text))ok=false;
// Existing staff replies may already request information: retain human review.
if(history.some(m=>m.staff))ok=false;
const target=c.current_message||{};
if(!c.reply_target?.message_id||/[\r\n]/.test(c.subject||''))ok=false;
if(target.reply_to&&target.reply_to!==target.from)ok=false;
if(ok)p.draft_body='Hi,\n\nThank you for contacting us. To help with your request, could you please provide:\n'+missing.map(k=>'- '+allowed[k]).join('\n')+'\n\nThank you,\nCustomer Support';
return {json:{...p,auto_clarification:ok,template_version:ok?'clarification-v1':null,todos:Array.isArray(d.todos)?d.todos:[]}};

const r=$json.result;
if(!r.allowed)throw new Error('Send was not approved');
function noCRLF(s){if(/[\r\n]/.test(s||''))throw new Error('Invalid mail header');return s;}
function validMail(s){noCRLF(s);if(!/^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$/.test(s))throw new Error('Invalid recipient');return s;}
const sender=validMail(r.mailbox),to=validMail(r.recipient);
const subject=noCRLF(r.subject||'');const subjectReply=/^re:/i.test(subject)?subject:'Re: '+subject;
const chunks=[];let chunk='';for(const ch of subjectReply){if(Buffer.byteLength(chunk+ch,'utf8')>42){chunks.push(chunk);chunk='';}chunk+=ch;}if(chunk)chunks.push(chunk);
const encodedSubject=chunks.map(c=>'=?UTF-8?B?'+Buffer.from(c).toString('base64')+'?=').join('\r\n ');
const anchor=noCRLF(r.in_reply_to);if(!/^<[^<>\s]+@[^<>\s]+>$/.test(anchor))throw new Error('Missing valid original Message-ID');
const msgid=noCRLF(r.rfc_message_id);
const text=Buffer.from(r.final_body,'utf8').toString('base64').match(/.{1,76}/g).join('\r\n');
const mime=['From: '+sender,'To: '+to,'Subject: '+encodedSubject,'Date: '+new Date().toUTCString(),'Message-ID: '+msgid,'In-Reply-To: '+anchor,'References: '+anchor,'MIME-Version: 1.0','Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','',''+text].join('\r\n');
return {json:{request_id:r.id,thread_id:r.thread_id,raw:Buffer.from(mime,'utf8').toString('base64url')}};

