BEGIN;
CREATE SCHEMA IF NOT EXISTS serviceatlas;
CREATE TABLE IF NOT EXISTS serviceatlas.mailboxes (
 mailbox text PRIMARY KEY, cursor_at timestamptz NOT NULL, config jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS serviceatlas.threads (
 mailbox text NOT NULL REFERENCES serviceatlas.mailboxes(mailbox), thread_id text NOT NULL,
 version bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'queued', snapshot jsonb NOT NULL DEFAULT '{}', fingerprint text NOT NULL DEFAULT '',
 lease_token uuid, lease_until timestamptz, execution_id text, attempts int NOT NULL DEFAULT 0,
 next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text, updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(mailbox,thread_id)
);
CREATE TABLE IF NOT EXISTS serviceatlas.messages (
 mailbox text NOT NULL, message_id text NOT NULL, thread_id text NOT NULL, raw jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(mailbox,message_id), FOREIGN KEY(mailbox,thread_id) REFERENCES serviceatlas.threads(mailbox,thread_id)
);
CREATE TABLE IF NOT EXISTS serviceatlas.drafts (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mailbox text NOT NULL, thread_id text NOT NULL, version bigint NOT NULL,
 revision int NOT NULL DEFAULT 1, status text NOT NULL, body text NOT NULL DEFAULT '', result jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(mailbox,thread_id) REFERENCES serviceatlas.threads(mailbox,thread_id), UNIQUE(mailbox,thread_id,version)
);
CREATE TABLE IF NOT EXISTS serviceatlas.send_requests (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), draft_id uuid NOT NULL UNIQUE REFERENCES serviceatlas.drafts(id),
 mailbox text NOT NULL, thread_id text NOT NULL, status text NOT NULL DEFAULT 'sending', rfc_message_id text NOT NULL UNIQUE,
 final_body text NOT NULL, recipient text NOT NULL, subject text NOT NULL, in_reply_to text NOT NULL,
 gmail_message_id text, execution_id text NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS serviceatlas.audit (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, draft_id uuid, actor text, action text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS serviceatlas.outbox (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dedup_key text NOT NULL UNIQUE, mailbox text NOT NULL, payload jsonb NOT NULL,
 status text NOT NULL DEFAULT 'queued', attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid,
 last_error text, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS serviceatlas.errors (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, execution_id text, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sa_thread_queue ON serviceatlas.threads(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS sa_outbox_queue ON serviceatlas.outbox(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS sa_message_thread ON serviceatlas.messages(mailbox,thread_id);
CREATE OR REPLACE FUNCTION serviceatlas.emit(k text,m text,p jsonb) RETURNS void LANGUAGE sql AS $$
 INSERT INTO serviceatlas.outbox(dedup_key,mailbox,payload) VALUES(k,m,p) ON CONFLICT(dedup_key) DO NOTHING;
$$;
CREATE OR REPLACE FUNCTION serviceatlas.human_failure(m text,tid text,v bigint,reason text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE did uuid;
BEGIN
 INSERT INTO serviceatlas.drafts(mailbox,thread_id,version,status,body,result)
 VALUES(m,tid,v,'needs_human','',jsonb_build_object('review_reasons',jsonb_build_array(reason)))
 ON CONFLICT(mailbox,thread_id,version) DO UPDATE SET status='needs_human',result=serviceatlas.drafts.result||excluded.result,updated_at=now()
 WHERE serviceatlas.drafts.status NOT IN ('sent','sending','send_unknown') RETURNING id INTO did;
 IF did IS NOT NULL THEN PERFORM serviceatlas.emit('terminal:'||did,m,jsonb_build_object('event','needs_human','draft_id',did,'thread_id',tid,'reason',reason)); END IF;
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.poll_config(m text,c jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE r serviceatlas.mailboxes; start_at timestamptz;
BEGIN
 start_at:=(c->>'initial_since')::timestamptz;
 IF start_at>now() THEN RAISE EXCEPTION 'initial_since must not be in the future'; END IF;
 INSERT INTO serviceatlas.mailboxes(mailbox,cursor_at,config) VALUES(lower(m),start_at,c)
 ON CONFLICT(mailbox) DO UPDATE SET config=excluded.config,updated_at=now();
 SELECT * INTO r FROM serviceatlas.mailboxes WHERE mailbox=lower(m);
 RETURN jsonb_build_object('mailbox',r.mailbox,'config',c,'scan_started_at',now(),'after_epoch',floor(extract(epoch FROM r.cursor_at-interval '5 minutes'))::bigint);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.ingest(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE a jsonb; m text:=p->>'mailbox'; tid text; n int; total int:=0;
BEGIN
 -- One transaction: receive, invalidate reviewed material and advance polling cursor.
 FOR a IN SELECT value FROM jsonb_array_elements(p->'messages') ORDER BY value->>'threadId',value->>'id' LOOP
  tid:=a->>'threadId';IF tid IS NULL OR a->>'id' IS NULL THEN CONTINUE;END IF;
  INSERT INTO serviceatlas.threads(mailbox,thread_id) VALUES(m,tid) ON CONFLICT DO NOTHING;
  PERFORM 1 FROM serviceatlas.threads WHERE mailbox=m AND thread_id=tid FOR UPDATE;
  INSERT INTO serviceatlas.messages VALUES(m,a->>'id',tid,a,now()) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n=ROW_COUNT;
  IF n>0 THEN
   UPDATE serviceatlas.threads SET version=version+1, status=CASE WHEN status='processing' THEN status ELSE 'queued' END,
    attempts=CASE WHEN status='processing' THEN attempts ELSE 0 END,next_attempt_at=now(),updated_at=now() WHERE mailbox=m AND thread_id=tid;
   UPDATE serviceatlas.drafts SET status='stale',updated_at=now() WHERE mailbox=m AND thread_id=tid AND status IN ('pending_review','needs_human');
   total:=total+1;
  END IF;
 END LOOP;
 UPDATE serviceatlas.mailboxes SET cursor_at=greatest(cursor_at,(p->>'scan_started_at')::timestamptz),updated_at=now() WHERE mailbox=m;
 RETURN jsonb_build_object('mailbox',m,'received',total);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.claim(m text,e text) RETURNS SETOF jsonb LANGUAGE plpgsql AS $$
DECLARE t serviceatlas.threads; c jsonb;
BEGIN
 SELECT * INTO t FROM serviceatlas.threads WHERE mailbox=m AND status IN ('queued','retry_ready') AND next_attempt_at<=now()
 ORDER BY updated_at FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 UPDATE serviceatlas.threads SET status='processing',lease_token=gen_random_uuid(),lease_until=now()+interval '15 minutes',execution_id=e,attempts=attempts+1
 WHERE mailbox=m AND thread_id=t.thread_id RETURNING * INTO t;
 SELECT config INTO c FROM serviceatlas.mailboxes WHERE mailbox=m;
 RETURN NEXT to_jsonb(t)||jsonb_build_object('config',c);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.snapshot(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE t serviceatlas.threads; a jsonb;
BEGIN
 SELECT * INTO t FROM serviceatlas.threads WHERE mailbox=p->>'mailbox' AND thread_id=p->>'thread_id' FOR UPDATE;
 IF t.lease_token IS DISTINCT FROM (p->>'lease_token')::uuid OR t.status<>'processing' OR t.lease_until<now() THEN RAISE EXCEPTION 'Worker lease expired'; END IF;
 -- Snapshot covers both customer and staff messages. Preserve complete Gmail JSON.
 IF t.fingerprint<>p->>'fingerprint' THEN
  UPDATE serviceatlas.drafts SET status='stale',updated_at=now() WHERE mailbox=t.mailbox AND thread_id=t.thread_id AND status IN ('pending_review','needs_human');
  t.version:=t.version+1;
 END IF;
 UPDATE serviceatlas.threads SET snapshot=p,fingerprint=p->>'fingerprint',version=t.version,updated_at=now() WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
 FOR a IN SELECT value FROM jsonb_array_elements(p->'raw_thread'->'messages') LOOP
  INSERT INTO serviceatlas.messages VALUES(t.mailbox,a->>'id',t.thread_id,a,now())
  ON CONFLICT(mailbox,message_id) DO UPDATE SET raw=excluded.raw;
 END LOOP;
 RETURN p||jsonb_build_object('version',t.version);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.finish(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE t serviceatlas.threads; d serviceatlas.drafts; s text:=p->>'status';
BEGIN
 IF s NOT IN ('pending_review','needs_human','ignored') THEN RAISE EXCEPTION 'Invalid completion status';END IF;
 SELECT * INTO t FROM serviceatlas.threads WHERE mailbox=p->>'mailbox' AND thread_id=p->>'thread_id' FOR UPDATE;
 IF t.lease_token IS DISTINCT FROM (p->>'lease_token')::uuid OR t.status<>'processing' OR t.lease_until<now() THEN
  RETURN jsonb_build_object('saved',false,'reason','lease_lost');END IF;
 IF t.version<>(p->>'version')::bigint OR coalesce(p->>'observed_fingerprint','')<>t.fingerprint THEN
  UPDATE serviceatlas.threads SET status='queued',version=version+1,lease_token=NULL,lease_until=NULL,attempts=0,updated_at=now() WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
  RETURN jsonb_build_object('saved',false,'reason','new_mail');
 END IF;
 INSERT INTO serviceatlas.drafts(mailbox,thread_id,version,status,body,result) VALUES(t.mailbox,t.thread_id,t.version,s,coalesce(p->>'draft_body',''),p)
 ON CONFLICT(mailbox,thread_id,version) DO UPDATE SET result=excluded.result,body=excluded.body,status=excluded.status,updated_at=now()
 WHERE serviceatlas.drafts.status NOT IN ('sending','sent') RETURNING * INTO d;
 UPDATE serviceatlas.threads SET status=s,lease_token=NULL,lease_until=NULL,last_error=NULL,updated_at=now() WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
 IF s<>'ignored' THEN PERFORM serviceatlas.emit('draft:'||d.id,t.mailbox,jsonb_build_object('event',s,'draft_id',d.id,'thread_id',t.thread_id,'reason',p->'review_reasons'));END IF;
 RETURN jsonb_build_object('saved',true,'draft_id',d.id,'status',s);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.get_review(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE d serviceatlas.drafts;t serviceatlas.threads;
BEGIN
 SELECT * INTO d FROM serviceatlas.drafts WHERE id=(p->>'draft_id')::uuid;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','draft_not_found');END IF;
 SELECT * INTO t FROM serviceatlas.threads WHERE mailbox=d.mailbox AND thread_id=d.thread_id;
 RETURN jsonb_build_object('ok',true,'draft',to_jsonb(d),'snapshot',t.snapshot,'request',p);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.review(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE d serviceatlas.drafts;t serviceatlas.threads;r serviceatlas.send_requests;actor text:=p->>'reviewer_id';action text:=p->>'action';rid uuid:=gen_random_uuid();body_text text;
BEGIN
 IF coalesce(actor,'')='' OR coalesce(action,'') NOT IN ('approve','edit','reject') OR coalesce(p->>'revision','') !~ '^[1-9][0-9]*$' THEN RETURN jsonb_build_object('allowed',false,'reason','invalid_review_request');END IF;
 SELECT * INTO d FROM serviceatlas.drafts WHERE id=(p->>'draft_id')::uuid;
 IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'reason','draft_not_found');END IF;
 -- Lock ordering: thread before draft, same as ingress and finish.
 SELECT * INTO t FROM serviceatlas.threads WHERE mailbox=d.mailbox AND thread_id=d.thread_id FOR UPDATE;
 SELECT * INTO d FROM serviceatlas.drafts WHERE id=d.id FOR UPDATE;
 IF d.revision<>(p->>'revision')::int OR d.version<>t.version OR d.status NOT IN ('pending_review','needs_human') THEN
  RETURN jsonb_build_object('allowed',false,'reason','stale_or_already_processed');END IF;
 IF coalesce(p->>'observed_fingerprint','')='' OR p->>'observed_fingerprint'<>t.fingerprint THEN
  UPDATE serviceatlas.drafts SET status='stale',updated_at=now() WHERE id=d.id;
  UPDATE serviceatlas.threads SET status='queued',version=version+1,attempts=0,next_attempt_at=now() WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
  RETURN jsonb_build_object('allowed',false,'reason','gmail_thread_changed');END IF;
 IF action='reject' THEN
  UPDATE serviceatlas.drafts SET status='rejected',revision=revision+1,updated_at=now() WHERE id=d.id;
  UPDATE serviceatlas.threads SET status='queued',version=version+1,attempts=0,next_attempt_at=now(),snapshot=snapshot||jsonb_build_object('review_feedback',p->>'reason') WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
  INSERT INTO serviceatlas.audit(draft_id,actor,action,detail) VALUES(d.id,actor,action,p);
  RETURN jsonb_build_object('allowed',false,'ok',true,'status','queued');END IF;
 body_text:=coalesce(p->>'body',d.body);
 IF length(trim(body_text))=0 OR length(body_text)>50000 THEN RETURN jsonb_build_object('allowed',false,'reason','invalid_body');END IF;
 IF action='edit' THEN
  UPDATE serviceatlas.drafts SET body=body_text,revision=revision+1,updated_at=now() WHERE id=d.id RETURNING * INTO d;
  INSERT INTO serviceatlas.audit(draft_id,actor,action,detail) VALUES(d.id,actor,action,p);
  RETURN jsonb_build_object('allowed',false,'ok',true,'status',d.status,'revision',d.revision);END IF;
 -- Recipient is always derived from Gmail headers, never from webhook input.
 IF coalesce(t.snapshot->'reply_target'->>'address','')='' OR coalesce(t.snapshot->'reply_target'->>'message_id','')='' THEN RETURN jsonb_build_object('allowed',false,'reason','reply_target_missing');END IF;
 INSERT INTO serviceatlas.send_requests(id,draft_id,mailbox,thread_id,rfc_message_id,final_body,recipient,subject,in_reply_to,execution_id)
 VALUES(rid,d.id,d.mailbox,d.thread_id,'<'||rid||'@'||split_part(d.mailbox,'@',2)||'>',body_text,t.snapshot->'reply_target'->>'address',t.snapshot->>'subject',t.snapshot->'reply_target'->>'message_id',p->>'execution_id')
 ON CONFLICT(draft_id) DO NOTHING RETURNING * INTO r;
 IF NOT FOUND THEN RETURN jsonb_build_object('allowed',false,'reason','send_already_claimed');END IF;
 UPDATE serviceatlas.drafts SET body=body_text,status='sending',revision=revision+1,updated_at=now() WHERE id=d.id;
 INSERT INTO serviceatlas.audit(draft_id,actor,action,detail) VALUES(d.id,actor,action,p);
 RETURN to_jsonb(r)||jsonb_build_object('allowed',true);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.send_result(rid uuid,gid text,gtid text,err text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE r serviceatlas.send_requests; ok boolean;
BEGIN
 SELECT * INTO r FROM serviceatlas.send_requests WHERE id=rid;
 IF NOT FOUND THEN RAISE EXCEPTION 'Unknown send request';END IF;
 PERFORM 1 FROM serviceatlas.threads WHERE mailbox=r.mailbox AND thread_id=r.thread_id FOR UPDATE;
 PERFORM 1 FROM serviceatlas.drafts WHERE id=r.draft_id FOR UPDATE;
 SELECT * INTO r FROM serviceatlas.send_requests WHERE id=rid FOR UPDATE;
 IF r.status='sent' THEN RETURN jsonb_build_object('ok',true,'status','sent','request_id',rid);END IF;
 ok:=coalesce(gid,'')<>'' AND gtid=r.thread_id;
 UPDATE serviceatlas.send_requests SET status=CASE WHEN ok THEN 'sent' ELSE 'unknown' END,gmail_message_id=CASE WHEN ok THEN gid ELSE NULL END,error=err,updated_at=now() WHERE id=rid;
 UPDATE serviceatlas.drafts SET status=CASE WHEN ok THEN 'sent' ELSE 'send_unknown' END,updated_at=now() WHERE id=r.draft_id;
 IF ok THEN UPDATE serviceatlas.threads SET status='sent',updated_at=now() WHERE mailbox=r.mailbox AND thread_id=r.thread_id AND status NOT IN ('queued','processing','retry_ready');END IF;
 PERFORM serviceatlas.emit('send:'||rid||':'||CASE WHEN ok THEN 'sent' ELSE 'unknown' END,r.mailbox,jsonb_build_object('event',CASE WHEN ok THEN 'sent' ELSE 'send_unknown' END,'draft_id',r.draft_id,'request_id',rid));
 RETURN jsonb_build_object('ok',ok,'status',CASE WHEN ok THEN 'sent' ELSE 'unknown' END,'request_id',rid);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.record_error(e text,p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE t serviceatlas.threads;r serviceatlas.send_requests;
BEGIN
 INSERT INTO serviceatlas.errors(execution_id,detail) VALUES(e,p);
 FOR t IN SELECT * FROM serviceatlas.threads WHERE execution_id=e AND status='processing' FOR UPDATE LOOP
  UPDATE serviceatlas.threads SET status=CASE WHEN attempts>=3 THEN 'needs_human' ELSE 'retry_ready' END,
   next_attempt_at=now()+interval '5 minutes',lease_token=NULL,lease_until=NULL,last_error=left(p::text,4000),updated_at=now()
  WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
  IF t.attempts>=3 THEN PERFORM serviceatlas.human_failure(t.mailbox,t.thread_id,t.version,left(p::text,2000));END IF;
  PERFORM serviceatlas.emit('error:'||e||':'||t.thread_id,t.mailbox,jsonb_build_object('event','execution_error','thread_id',t.thread_id,'execution_id',e));
 END LOOP;
 FOR r IN SELECT * FROM serviceatlas.send_requests WHERE execution_id=e AND status='sending' LOOP
  PERFORM serviceatlas.send_result(r.id,NULL,NULL,left(p::text,4000));
 END LOOP;
 RETURN jsonb_build_object('recorded',true);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.recover() RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE t serviceatlas.threads;r serviceatlas.send_requests;n int:=0;
BEGIN
 FOR t IN SELECT * FROM serviceatlas.threads WHERE status='processing' AND lease_until<now() FOR UPDATE SKIP LOCKED LOOP
  UPDATE serviceatlas.threads SET status=CASE WHEN attempts>=3 THEN 'needs_human' ELSE 'retry_ready' END,lease_token=NULL,lease_until=NULL,next_attempt_at=now(),last_error='worker_timeout' WHERE mailbox=t.mailbox AND thread_id=t.thread_id;
  IF t.attempts>=3 THEN PERFORM serviceatlas.human_failure(t.mailbox,t.thread_id,t.version,'worker_timeout_retry_limit');END IF;n:=n+1;
 END LOOP;
 FOR r IN SELECT * FROM serviceatlas.send_requests WHERE status='sending' AND created_at<now()-interval '5 minutes' LOOP PERFORM serviceatlas.send_result(r.id,NULL,NULL,'send_timeout');END LOOP;
 UPDATE serviceatlas.outbox SET status=CASE WHEN attempts>=5 THEN 'failed' ELSE 'queued' END,lease_until=NULL WHERE status='sending' AND lease_until<now();
 RETURN jsonb_build_object('recovered',n);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.claim_notice() RETURNS SETOF jsonb LANGUAGE plpgsql AS $$
DECLARE o serviceatlas.outbox;c jsonb;
BEGIN
 SELECT * INTO o FROM serviceatlas.outbox WHERE status='queued' AND next_attempt_at<=now() ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN;END IF;
 UPDATE serviceatlas.outbox SET status='sending',attempts=attempts+1,lease_until=now()+interval '2 minutes',lease_token=gen_random_uuid() WHERE id=o.id RETURNING * INTO o;
 SELECT config INTO c FROM serviceatlas.mailboxes WHERE mailbox=o.mailbox;
 RETURN NEXT to_jsonb(o)||jsonb_build_object('config',c);
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.notice_result(i uuid,token uuid,ok boolean,err text) RETURNS jsonb LANGUAGE plpgsql AS $$
BEGIN
 UPDATE serviceatlas.outbox SET status=CASE WHEN ok THEN 'sent' WHEN attempts>=5 THEN 'failed' ELSE 'queued' END,
  lease_until=NULL,next_attempt_at=now()+interval '5 minutes',last_error=err WHERE id=i AND lease_token=token AND status='sending';
 RETURN jsonb_build_object('ok',ok);
END $$;
COMMIT;

CREATE OR REPLACE FUNCTION serviceatlas.claim_for(m text,e text,target text) RETURNS SETOF jsonb LANGUAGE plpgsql AS $$
DECLARE t serviceatlas.threads; c jsonb;
BEGIN
 SELECT * INTO t FROM serviceatlas.threads WHERE mailbox=m AND (target IS NULL OR thread_id=target) AND status IN ('queued','retry_ready') AND next_attempt_at<=now()
 ORDER BY updated_at FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 UPDATE serviceatlas.threads SET status='processing',lease_token=gen_random_uuid(),lease_until=now()+interval '15 minutes',execution_id=e,attempts=attempts+1
 WHERE mailbox=m AND thread_id=t.thread_id RETURNING * INTO t;
 SELECT config INTO c FROM serviceatlas.mailboxes WHERE mailbox=m;
 RETURN NEXT to_jsonb(t)||jsonb_build_object('config',c);
END $$;

CREATE OR REPLACE FUNCTION serviceatlas.accept_mail(p jsonb,e text) RETURNS SETOF jsonb LANGUAGE plpgsql AS $$
BEGIN
 PERFORM serviceatlas.poll_config(p->>'mailbox',p->'config');
 IF p->'message'->>'id' IS NOT NULL THEN
  PERFORM serviceatlas.ingest(jsonb_build_object('mailbox',p->>'mailbox','messages',jsonb_build_array(p->'message'),'scan_started_at',now()));
 END IF;
 RETURN QUERY SELECT * FROM serviceatlas.claim_for(p->>'mailbox',e,p->'message'->>'threadId');
END $$;
CREATE OR REPLACE FUNCTION serviceatlas.auto_clarify(did uuid,fp text,e text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE d serviceatlas.drafts; r jsonb;
BEGIN
 SELECT * INTO d FROM serviceatlas.drafts WHERE id=did;
 IF NOT FOUND OR d.status<>'pending_review' OR (d.result->>'auto_clarification') IS DISTINCT FROM 'true' THEN RETURN jsonb_build_object('allowed',false); END IF;
 r:=serviceatlas.review(jsonb_build_object('draft_id',did,'revision',d.revision,'action','approve','reviewer_id','system:clarification-template-v1','observed_fingerprint',fp,'execution_id',e));
 IF r->>'allowed'='true' THEN
  UPDATE serviceatlas.outbox SET status='sent' WHERE dedup_key='draft:'||did;
 END IF;
 RETURN r;
END $$;
